-- Operator executes BEGIN, this script, then ROLLBACK. No test data is committed.
DO $test$
DECLARE m uuid:='6bf48c58-83b6-467c-b530-12c129a9771c'; u uuid:='da1be905-be1e-4af6-9103-db05749294a3'; cat uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); req uuid:=gen_random_uuid(); req2 uuid:=gen_random_uuid(); q jsonb; a jsonb; b jsonb; fx numeric; bal numeric; failed boolean; original_fixed numeric; base_hash text;
BEGIN
 IF (SELECT count(*) FROM auth.users WHERE id IN(m,u) AND raw_app_meta_data->>'f90_security_fixture'='true')<>2 THEN RAISE EXCEPTION 'test fixture guard'; END IF;
 SELECT md5(string_agg(id::text||price::text||commerce::text,',' ORDER BY id)) INTO base_hash FROM public.products;
 UPDATE public.profiles SET account_status='active',vip_override=1,is_verified=true WHERE id IN(m,u);
 UPDATE public.f90_user_roles SET role=CASE WHEN user_id=m THEN 'manager' ELSE 'customer' END WHERE user_id IN(m,u);
 UPDATE public.f90_wallets SET balance_usd=1000 WHERE user_id=u;
 DELETE FROM public.f90_user_discounts WHERE user_id=u;
 UPDATE public.f90_vip_tiers SET discount_percent=0 WHERE level=1;
 INSERT INTO public.categories(id,name,slug) VALUES(cat,'معزول لا ينشر','isolated-'||cat);
 INSERT INTO public.products(id,name,slug,category_id,price,currency,commerce) VALUES(prod,'اختبار تسعير معزول','isolated-'||prod,cat,114,'USD',jsonb_build_object('type','quantity','prices',jsonb_build_object('USD',114),'unit_quantity',1000000,'quantity_min',1000,'quantity_max',1000000000,'quantity_step',1000,'fulfillment','manual','fields','[]'::jsonb,'currency_pricing',jsonb_build_object('enabled',true,'unit_quantity',1000000,'prices',jsonb_build_object('USD',114,'ILS',375,'JOD',80))));
 PERFORM public.f90_currency_pricing_toggle(m,true,'isolated enabled test');
 UPDATE public.profiles SET account_currency='USD' WHERE id=m;
 q:=public.f90_quote_currency(NULL,prod,1000000,'','ILS');IF (q->>'total_currency')::numeric<>375 THEN RAISE EXCEPTION 'Guest selected currency failed'; END IF;
 UPDATE public.profiles SET account_currency='JOD' WHERE id=u;
 q:=public.f90_quote_currency(u,prod,1000000,'','ILS');
 IF q->>'price_currency'<>'JOD' OR (q->>'total_currency')::numeric<>80 THEN RAISE EXCEPTION 'JOD fixed price or account currency authority failed %',q; END IF;
 q:=public.f90_quote(u,prod,500000,'');IF (q->>'total_currency')::numeric<>40 THEN RAISE EXCEPTION 'Quantity scaling failed'; END IF;
 SELECT per_usd INTO fx FROM public.f90_rates WHERE currency='JOD';
 UPDATE public.f90_rates SET per_usd=0.8 WHERE currency='JOD';
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_currency')::numeric<>80 OR (q->>'total_usd')::numeric<>100 THEN RAISE EXCEPTION 'Independent price followed FX'; END IF;
 UPDATE public.f90_rates SET per_usd=fx WHERE currency='JOD';
 UPDATE public.profiles SET account_currency='ILS' WHERE id=u;
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_currency')::numeric<>375 THEN RAISE EXCEPTION 'ILS fixed price failed'; END IF;
 UPDATE public.profiles SET account_currency='USD' WHERE id=u;
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_usd')::numeric<>114 THEN RAISE EXCEPTION 'USD fixed price failed'; END IF;
 PERFORM public.f90_set_user_markup(m,u,10,true);
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_usd')::numeric<>125.4 THEN RAISE EXCEPTION 'User markup failed'; END IF;
 q:=public.f90_quote(m,prod,1000000,'');IF (q->>'total_usd')::numeric<>114 THEN RAISE EXCEPTION 'Markup affected another user'; END IF;
 PERFORM public.f90_set_user_discount(m,u,10);
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_usd')::numeric<>112.86 THEN RAISE EXCEPTION 'Markup/discount ordering failed'; END IF;
 PERFORM public.f90_set_user_markup(m,u,10,false);PERFORM public.f90_set_user_discount(m,u,0);
 PERFORM public.f90_currency_pricing_toggle(m,false,'isolated disabled test');
 UPDATE public.profiles SET account_currency='JOD' WHERE id=u;
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_usd')::numeric<>114 OR (q->>'currency_price_fixed')::boolean THEN RAISE EXCEPTION 'Global disable changed base price'; END IF;
 PERFORM public.f90_currency_pricing_toggle(m,true,'isolated enabled test');
 UPDATE public.products SET commerce=jsonb_set(commerce,'{currency_pricing,enabled}','false') WHERE id=prod;
 q:=public.f90_quote(u,prod,1000000,'');IF (q->>'total_usd')::numeric<>114 THEN RAISE EXCEPTION 'Per-product disable failed'; END IF;
 UPDATE public.products SET commerce=jsonb_set(commerce,'{currency_pricing,enabled}','true') WHERE id=prod;
 -- Fixed packs use the pack quantity, not one artificial coin or the supplier cost basis.
 UPDATE public.products SET commerce=commerce||'{"type":"fixed","pack_quantity":500000}'::jsonb WHERE id=prod;
 q:=public.f90_quote(u,prod,1,'');IF (q->>'total_currency')::numeric<>40 THEN RAISE EXCEPTION 'Fixed pack price failed'; END IF;
 UPDATE public.products SET commerce=commerce||'{"type":"quantity"}'::jsonb WHERE id=prod;
 failed:=false;BEGIN PERFORM public.f90_quote(u,prod,1001,'');EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_QUANTITY';END;IF NOT failed THEN RAISE EXCEPTION 'Quantity guard failed';END IF;
 q:=public.f90_quote(u,prod,1000000,'');
 a:=public.f90_checkout(u,prod,1000000,'{"account_id":"isolated"}','isolated-'||req,(q->>'total_usd')::numeric,'');
 b:=public.f90_checkout(u,prod,1000000,'{"account_id":"isolated"}','isolated-'||req,(q->>'total_usd')::numeric,'');
 IF a->>'id'<>b->>'id' OR (a->>'total_currency')::numeric<>80 OR a->>'price_currency'<>'JOD' THEN RAISE EXCEPTION 'Order snapshot/idempotency failed'; END IF;
 IF (SELECT count(*) FROM public.f90_wallet_ledger WHERE user_id=u AND unique_key='purchase:'||(a->>'id'))<>1 THEN RAISE EXCEPTION 'Purchase double charged'; END IF;
 failed:=false;BEGIN PERFORM public.f90_checkout(u,prod,2000000,'{"account_id":"isolated"}','isolated-'||req,1,'');EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_IDEMPOTENCY_CONFLICT';END;IF NOT failed THEN RAISE EXCEPTION 'Checkout reference conflict failed';END IF;
 SELECT balance_usd INTO bal FROM public.f90_wallets WHERE user_id=u;
 SELECT per_usd INTO fx FROM public.f90_rates WHERE currency='ILS';
 a:=public.f90_finance_adjust_currency(m,u,fx*10,'ILS','isolated ILS adjustment',req2,bal,fx);
 IF (a->>'amount_usd')::numeric<>10 THEN RAISE EXCEPTION 'ILS conversion failed'; END IF;
 UPDATE public.f90_rates SET per_usd=fx+0.1 WHERE currency='ILS';
 b:=public.f90_finance_adjust_currency(m,u,fx*10,'ILS','isolated ILS adjustment',req2,bal,fx);
 IF NOT (b->>'replayed')::boolean OR (SELECT balance_usd FROM public.f90_wallets WHERE user_id=u)<>bal+10 THEN RAISE EXCEPTION 'Currency replay double credit'; END IF;
 UPDATE public.f90_rates SET per_usd=fx WHERE currency='ILS';
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(m,u,fx*11,'ILS','isolated ILS adjustment',req2,bal,fx);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_IDEMPOTENCY_CONFLICT';END;IF NOT failed THEN RAISE EXCEPTION 'Currency reference conflict failed';END IF;
 SELECT balance_usd INTO bal FROM public.f90_wallets WHERE user_id=u;SELECT per_usd INTO fx FROM public.f90_rates WHERE currency='JOD';
 a:=public.f90_finance_adjust_currency(m,u,fx*10,'JOD','isolated JOD adjustment',gen_random_uuid(),bal,fx);IF (a->>'amount_usd')::numeric<>10 THEN RAISE EXCEPTION 'JOD conversion failed';END IF;
 SELECT balance_usd INTO bal FROM public.f90_wallets WHERE user_id=u;
 a:=public.f90_finance_adjust_currency(m,u,10,'USD','isolated USD adjustment',gen_random_uuid(),bal,1);IF (a->>'amount_usd')::numeric<>10 THEN RAISE EXCEPTION 'USD conversion failed';END IF;
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(m,u,1,'ILS','isolated changed exchange',gen_random_uuid(),bal,999);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_RATE_CHANGED';END;IF NOT failed THEN RAISE EXCEPTION 'Changed FX guard failed';END IF;
 failed:=false;BEGIN PERFORM public.f90_set_user_markup(u,m,10,true);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_FORBIDDEN';END;IF NOT failed THEN RAISE EXCEPTION 'Customer markup control allowed';END IF;
 -- Credit guards never mutate the wallet when the balance, permissions or amount are invalid.
 SELECT balance_usd INTO bal FROM public.f90_wallets WHERE user_id=u;
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(m,u,-bal-10,'USD','isolated insufficient debit',gen_random_uuid(),bal,1);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_INSUFFICIENT_BALANCE';END;IF NOT failed THEN RAISE EXCEPTION 'Negative wallet permitted';END IF;
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(m,u,1,'USD','isolated stale balance',gen_random_uuid(),0,1);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_BALANCE_CHANGED';END;IF NOT failed THEN RAISE EXCEPTION 'Stale balance permitted';END IF;
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(u,m,1,'USD','isolated permission test',gen_random_uuid(),0,1);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_FORBIDDEN';END;IF NOT failed THEN RAISE EXCEPTION 'Customer credit permitted';END IF;
 failed:=false;BEGIN PERFORM public.f90_finance_adjust_currency(m,u,1,'SAR','isolated currency test',gen_random_uuid(),bal,4);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_AMOUNT';END;IF NOT failed THEN RAISE EXCEPTION 'Unsupported credit currency permitted';END IF;
 UPDATE public.f90_wallets SET balance_usd=0 WHERE user_id=u;
 q:=public.f90_quote(u,prod,1000000,'');
 failed:=false;BEGIN PERFORM public.f90_checkout(u,prod,1000000,'{"account_id":"isolated"}','insufficient-'||req,(q->>'total_usd')::numeric,'');EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='F90_INSUFFICIENT_BALANCE';END;IF NOT failed THEN RAISE EXCEPTION 'Insufficient purchase permitted';END IF;
 UPDATE public.f90_wallets SET balance_usd=bal WHERE user_id=u;
 IF (SELECT md5(string_agg(id::text||price::text||commerce::text,',' ORDER BY id)) FROM public.products WHERE id<>prod)<>base_hash THEN RAISE EXCEPTION 'Existing product prices changed'; END IF;
 IF has_function_privilege('authenticated','public.f90_finance_adjust_currency(uuid,uuid,numeric,text,text,uuid,numeric,numeric)','EXECUTE') OR has_table_privilege('authenticated','public.f90_currency_adjustments','SELECT') THEN RAISE EXCEPTION 'New financial controls exposed'; END IF;
END $test$;
SELECT 'PASS: fixed USD/ILS/JOD, independent FX, quantities/packs, per-user markup/discount, switches, checkout idempotency/snapshot, FX wallet credits/replays/conflicts, role/grant guards, unchanged existing products; all rolled back' AS result;
